public partial class ShowService
{
    private async partial Task<Error?> CheckCapacityAsync(Domain.Show aggregate, CancellationToken cancellationToken)
    {
        var venue = await VenueRepository.FindAsync(aggregate.VenueId, cancellationToken);
        if (venue is null)
        {
            return Error.Invalid(new Dictionary<string, string[]> { ["VenueId"] = ["Unknown venue"] });
        }
        if (aggregate.TicketTiers.Sum(t => (long)t.Quota) > venue.Capacity)
        {
            return Error.Invalid(new Dictionary<string, string[]> { ["TicketTiers"] = ["The quotas exceed the capacity of the venue"] });
        }
        return null;
    }
}
