namespace Acme.Ticketing.Tests;

[TestClass]
public class TicketingScenarioTests : ApiTestBase
{
    private static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web);

    private async Task<JsonElement> CreateVenue(string name = "Arena", int capacity = 100)
    {
        var response = await Client.PostAsJsonAsync("/venues", new { name, capacity, address = new { street = "1 Main", city = "Paris", postalCode = "75001" } });
        Assert.AreEqual(HttpStatusCode.Created, response.StatusCode);
        return await response.Content.ReadFromJsonAsync<JsonElement>();
    }

    private async Task<JsonElement> CreateShow(Guid venueId, int status = 1, DateTime? startsAt = null, int quota = 5)
    {
        var response = await Client.PostAsJsonAsync("/shows", new
        {
            title = "Concert",
            startsAt = startsAt ?? DateTime.UtcNow.AddDays(10),
            status,
            venueId,
            ticketTiers = new[] { new { name = "Standard", price = 10.5m, quota, sold = 99 } },
        });
        Assert.AreEqual(HttpStatusCode.Created, response.StatusCode, await response.Content.ReadAsStringAsync());
        return await response.Content.ReadFromJsonAsync<JsonElement>();
