        var booking = await ok.Content.ReadFromJsonAsync<JsonElement>();
        Assert.AreEqual(31.5m, booking.GetProperty("totalPrice").GetDecimal());
        Assert.AreEqual(HttpStatusCode.Conflict, (await Book(showId)).StatusCode);
        Assert.IsTrue((await Client.GetFromJsonAsync<JsonElement>($"/shows/{showId}")).GetProperty("isSoldOut").GetBoolean());

        var id = booking.GetProperty("id").GetGuid();
        Assert.AreEqual(HttpStatusCode.OK, (await Client.GetAsync($"/bookings/{id}")).StatusCode);
        Assert.AreEqual(1, (await Client.GetFromJsonAsync<JsonElement>("/bookings")).GetProperty("totalCount").GetInt32());

        var draft = await CreateShow(venueId, status: 0);
        Assert.AreEqual(HttpStatusCode.Conflict, (await Book(draft.GetProperty("id").GetGuid())).StatusCode);
        var past = await CreateShow(venueId, startsAt: DateTime.UtcNow.AddDays(-1));
        Assert.AreEqual(HttpStatusCode.Conflict, (await Book(past.GetProperty("id").GetGuid())).StatusCode);
    }

    [TestMethod]
    public async Task RightsAreEnforced()
    {
        AuthenticateAs();
        Assert.AreEqual(HttpStatusCode.OK, (await Client.GetAsync("/venues")).StatusCode);
        Assert.AreEqual(HttpStatusCode.Forbidden, (await Client.GetAsync("/bookings")).StatusCode);
        Assert.AreEqual(HttpStatusCode.Forbidden, (await Client.PostAsJsonAsync("/venues", new { })).StatusCode);
        AuthenticateAs("ManageVenues");
        Assert.AreEqual(HttpStatusCode.Created, (await Client.PostAsJsonAsync("/venues", new { name = "V", capacity = 1, address = new { street = "s", city = "c", postalCode = "p" } })).StatusCode);
        Assert.AreEqual(HttpStatusCode.Forbidden, (await Client.DeleteAsync($"/shows/{Guid.NewGuid()}")).StatusCode);
    }
}

[TestClass]
public class JwtTests : ApiTestBase
{
    protected override bool UseTestAuthentication => false;

    private static string Token(string key, DateTime expires, params string[] rights)
    {
        var bytes = Encoding.UTF8.GetBytes(key.PadRight(32));
        var jwt = new JwtSecurityToken(claims: rights.Select(r => new Claim("right", r)), expires: expires,
            notBefore: expires.AddHours(-2),
            signingCredentials: new SigningCredentials(new SymmetricSecurityKey(bytes), SecurityAlgorithms.HmacSha256));
        return new JwtSecurityTokenHandler().WriteToken(jwt);
    }

    [TestMethod]
    public async Task ValidatesSignatureLifetimeAndRights()
    {
        Client.DefaultRequestHeaders.Authorization = null;
        Assert.AreEqual(HttpStatusCode.Unauthorized, (await Client.GetAsync("/venues")).StatusCode);

        const string key = "change-me-development-signing-key";
        Client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", Token(key, DateTime.UtcNow.AddHours(1)));
        Assert.AreEqual(HttpStatusCode.OK, (await Client.GetAsync("/venues")).StatusCode);
        Assert.AreEqual(HttpStatusCode.Forbidden, (await Client.GetAsync("/bookings")).StatusCode);

        Client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", Token(key, DateTime.UtcNow.AddHours(1), "*"));
        Assert.AreEqual(HttpStatusCode.OK, (await Client.GetAsync("/bookings")).StatusCode);

        Client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", Token("another-key", DateTime.UtcNow.AddHours(1), "*"));
        Assert.AreEqual(HttpStatusCode.Unauthorized, (await Client.GetAsync("/venues")).StatusCode);

        Client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", Token(key, DateTime.UtcNow.AddHours(-1), "*"));
        Assert.AreEqual(HttpStatusCode.Unauthorized, (await Client.GetAsync("/venues")).StatusCode);
    }
}
